/**
 * identity.primary @sequenceStart / @sequenceName through the CLI against a real Postgres, on
 * the shadow path `meta verify --db` and `meta migrate --from-db` take by default (env-gated on
 * MIGRATE_TS_PG_URL; a throwaway database per test).
 *
 *  - A model that declares NO sequence sees no change from one: a live sequence left behind by
 *    a table rename, with a non-default start, verifies clean and plans nothing, and a fresh
 *    CREATE stays plain `GENERATED BY DEFAULT AS IDENTITY`.
 *  - A declared start and name that differ from the live sequence are altered in place, and the
 *    counter really moves: the next insert takes the declared start.
 */
import { describe, test, expect } from "bun:test";
import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import pg from "pg";
import { run } from "../../src/index.js";

const PG_URL = process.env.MIGRATE_TS_PG_URL;

function model(pk: Record<string, unknown>): string {
  return JSON.stringify({ "metadata.root": { package: "acme", children: [
    { "object.entity": { name: "Ticket", children: [
      { "source.rdb": { "@table": "Ticket" } },
      { "field.int": { name: "id", "@column": "Id" } },
      { "field.string": { name: "label", "@column": "Label" } },
      { "identity.primary": { name: "pk", "@fields": "id", "@generation": "increment", ...pk } },
    ] } },
  ] } });
}

async function withDatabase(fn: (url: string, client: pg.Client) => Promise<void>): Promise<void> {
  const admin = new pg.Client({ connectionString: PG_URL });
  await admin.connect();
  const db = `mt_seq_${Date.now()}_${Math.floor(Math.random() * 1e6)}`;
  await admin.query(`CREATE DATABASE ${db}`);
  const url = new URL(PG_URL!);
  url.pathname = `/${db}`;
  const client = new pg.Client({ connectionString: url.toString() });
  await client.connect();
  try {
    await fn(url.toString(), client);
  } finally {
    await client.end();
    await admin.query(`DROP DATABASE IF EXISTS ${db} WITH (FORCE)`);
    await admin.end();
  }
}

function project(pk: Record<string, unknown>): string {
  const root = mkdtempSync(join(tmpdir(), "identity-sequence-pg-"));
  mkdirSync(join(root, "metaobjects"), { recursive: true });
  mkdirSync(join(root, ".metaobjects", "migrations"), { recursive: true });
  writeFileSync(join(root, "metaobjects", "meta.acme.json"), model(pk), "utf8");
  writeFileSync(join(root, ".metaobjects", "config.json"), JSON.stringify({ schema_version: 1, migrate: { dialect: "postgres" } }), "utf8");
  return root;
}

async function captured(argv: string[]): Promise<{ exit: number; out: string }> {
  const lines: string[] = [];
  const keep = (...a: unknown[]): void => { lines.push(a.map(String).join(" ")); };
  const orig = [console.log, console.error, console.warn] as const;
  console.log = keep; console.error = keep; console.warn = keep;
  try {
    return { exit: await run(argv), out: lines.join("\n") };
  } finally {
    [console.log, console.error, console.warn] = orig;
  }
}

describe("identity.primary sequence on a real Postgres (env-gated)", () => {
  if (PG_URL === undefined || PG_URL.length === 0) {
    test.skip("skipped — MIGRATE_TS_PG_URL not set", () => {});
    return;
  }

  test("a model that declares no sequence: a renamed table's live sequence verifies clean and plans nothing", async () => {
    await withDatabase(async (url, client) => {
      await client.query(`CREATE TABLE "OldTicket" ("Id" integer GENERATED BY DEFAULT AS IDENTITY (START WITH 1000) PRIMARY KEY, "Label" text)`);
      await client.query(`ALTER TABLE "OldTicket" RENAME TO "Ticket"`);
      const root = project({});
      try {
        const verify = await captured(["verify", "--cwd", root, "--db", url]);
        expect(verify.out).not.toContain("alter-sequence");
        expect(verify.exit).toBe(0);
        const plan = await captured(["migrate", "--cwd", root, "--db", url, "--from-db", "--dry-run"]);
        expect(plan.out).not.toContain("SEQUENCE");
      } finally {
        rmSync(root, { recursive: true, force: true });
      }
    });
  });

  test("a model that declares no sequence: a fresh CREATE is plain IDENTITY", async () => {
    await withDatabase(async (url) => {
      const root = project({});
      try {
        const plan = await captured(["migrate", "--cwd", root, "--db", url, "--from-db", "--dry-run"]);
        expect(plan.out).toContain("GENERATED BY DEFAULT AS IDENTITY");
        expect(plan.out).not.toContain("SEQUENCE NAME");
      } finally {
        rmSync(root, { recursive: true, force: true });
      }
    });
  });

  test("a declared start and name that differ are altered in place, and the next insert takes the start", async () => {
    await withDatabase(async (url, client) => {
      await client.query(`CREATE TABLE "Ticket" ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Label" text)`);
      await client.query(`INSERT INTO "Ticket" ("Label") VALUES ('seeded')`);
      const root = project({ "@sequenceStart": 1000000000, "@sequenceName": "Legacy_Id_seq" });
      try {
        const drift = await captured(["verify", "--cwd", root, "--db", url]);
        expect(drift.exit).toBe(1);
        expect(drift.out).toContain("alter-sequence");
        const applied = await captured(["migrate", "--cwd", root, "--db", url, "--from-db", "--slug", "seq", "--apply"]);
        expect(applied.exit).toBe(0);
        const { rows } = await client.query(`INSERT INTO "Ticket" ("Label") VALUES ('next') RETURNING "Id"`);
        expect(Number(rows[0].Id)).toBe(1000000000);
        const seq = await client.query(`SELECT pg_get_serial_sequence('"Ticket"', 'Id') AS s`);
        expect(seq.rows[0].s).toBe('public."Legacy_Id_seq"');
        const clean = await captured(["verify", "--cwd", root, "--db", url]);
        expect(clean.exit).toBe(0);
      } finally {
        rmSync(root, { recursive: true, force: true });
      }
    });
  });
});
